        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 35.666666666666664, 'max': 79.0, 'label': 'BETA'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'label': 'EMPTY'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 82.33333333333333, 'max': 119.0, 'label': 'BETA'})
